package lk.sliit.nutricare.health;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="health_checks")public class HealthCheck{@Id private UUID id;@Column(nullable=false)private UUID patientId;@Column(nullable=false)private UUID practitionerId;private BigDecimal weightKg;private BigDecimal bmi;private Integer systolic;private Integer diastolic;private BigDecimal bloodSugar;private BigDecimal temperature;@Column(length=2000)private String notes;@Column(nullable=false)private Instant recordedAt;protected HealthCheck(){}public HealthCheck(UUID p,UUID d,BigDecimal w,BigDecimal bmi,Integer sys,Integer dia,BigDecimal sugar,BigDecimal temp,String notes){id=UUID.randomUUID();patientId=p;practitionerId=d;weightKg=w;this.bmi=bmi;systolic=sys;diastolic=dia;bloodSugar=sugar;temperature=temp;this.notes=notes;recordedAt=Instant.now();}public UUID getId(){return id;}public UUID getPatientId(){return patientId;}public UUID getPractitionerId(){return practitionerId;}public BigDecimal getWeightKg(){return weightKg;}public BigDecimal getBmi(){return bmi;}public Integer getSystolic(){return systolic;}public Integer getDiastolic(){return diastolic;}public BigDecimal getBloodSugar(){return bloodSugar;}public BigDecimal getTemperature(){return temperature;}public String getNotes(){return notes;}public Instant getRecordedAt(){return recordedAt;}}
